<script>
document.addEventListener('DOMContentLoaded',()=>{
'use strict';
const $=id=>document.getElementById(id), esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const serverVehicles=@json($registeredVehicles);const serverCouriers=@json($approvedCouriers);const serverArchives=@json($fleetArchives);
const asArray=v=>Array.isArray(v)?v:(Array.isArray(v?.data)?v.data:null);
const api=async(url,options={})=>{const response=await fetch(url,{credentials:'same-origin',...options,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||'',...(options.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.message||'Unable to complete the request.');return body};
const fullName=r=>[r.first_name,r.middle_name,r.last_name].filter(Boolean).join(' ')||r.full_name||r.name||'Unknown Courier';
const initials=s=>String(s).split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();
const date=v=>{if(!v)return '—';let d=new Date(v);return isNaN(d.getTime())?String(v):new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(d)};
const val=(r,...keys)=>{for(let k of keys){let v=r?.[k];if(v!==undefined&&v!==null&&v!=='')return v;}return '—'};
const field=(label,v)=>`<div class="cr-field"><label>${esc(label)}</label><strong>${esc(v)}</strong></div>`;
const section=(title,body)=>`<h3 class="cr-section">${esc(title)}</h3>${body}`;
const serverVehicleRows=asArray(serverVehicles)||[],serverCourierRows=asArray(serverCouriers)||[];
function vehicles(){return serverVehicleRows.map(v=>({...v,id:String(v.id)}));}
function couriers(){return serverCourierRows.filter(c=>String(c.status||'').toLowerCase()==='approved').map(c=>({...c,id:String(c.id)}));}
let archive=(asArray(serverArchives)||[]).map(a=>({...a,id:String(a.id)}));
let activeTab='vehicles',page=1,selected=null;
const key=(type,id)=>type+':'+String(id);
const isArchived=(type,id)=>archive.some(a=>a.key===key(type,id));
const available=type=>(type==='vehicles'?vehicles():couriers()).filter(r=>!isArchived(type,r.id));
function flash(title,msg,error=false){const el=$('vdFlash');el.classList.toggle('error',error);$('vdFlashTitle').textContent=title;$('vdFlashMsg').textContent=msg;$('vdFlashIcon').innerHTML=error?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 5 14 14M19 5 5 19"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 12 4 4L19 6"/></svg>';el.hidden=false;clearTimeout(flash.timer);flash.timer=setTimeout(()=>el.hidden=true,4000)}
function setModal(id,show){$(id).hidden=!show;document.body.style.overflow=document.querySelector('.cr-modal:not([hidden])')?'hidden':'';}
function closeAll(){document.querySelectorAll('.cr-modal').forEach(m=>m.hidden=true);document.body.style.overflow='';}
function draw(){let vs=available('vehicles'),cs=available('couriers');$('vdVehiclesCount').textContent=vs.length;$('vdCouriersCount').textContent=cs.length;$('vdTrashCount').textContent=archive.length;$('vdTrashCount').hidden=!archive.length;const q=$('vdSearch').value.toLowerCase().trim();const rows=(activeTab==='vehicles'?vs:cs).filter(r=>JSON.stringify(r).toLowerCase().includes(q));const max=Math.max(1,Math.ceil(rows.length/8));page=Math.max(1,Math.min(page,max));const view=rows.slice((page-1)*8,page*8);$('vdVehicleRows').innerHTML=activeTab==='vehicles'?(view.map(r=>`<tr data-key="${esc(r.id)}"><td><strong>${esc(val(r,'name','vehicle_name','model'))}</strong></td><td><strong>${esc(val(r,'plate_number'))}</strong></td><td>${esc(val(r,'type','vehicle_type'))}</td><td>${esc(val(r,'driver_name','assigned_driver'))}</td><td>${esc(date(r.registration_date||r.created_at))}</td><td><span class="vd-tag ${String(r.availability).toLowerCase()==='available'?'':'offline'}">${esc(val(r,'availability','status'))}</span></td></tr>`).join('')||'<tr><td colspan="6" class="cr-empty">No registered vehicles found.</td></tr>') : ''; $('vdCourierRows').innerHTML=activeTab==='couriers'?(view.map(r=>`<tr data-key="${esc(r.id)}"><td><div class="cr-person"><span class="cr-avatar">${esc(initials(fullName(r)))}</span><strong>${esc(fullName(r))}</strong></div></td><td>${esc(val(r,'email'))}</td><td>${esc(val(r,'phone','contact_no','contact_number'))}</td><td>${esc(val(r,'vehicle','vehicle_type'))} · ${esc(val(r,'plate_number'))}</td><td>${esc(date(r.reviewed_at||r.approved_at))}</td></tr>`).join('')||'<tr><td colspan="5" class="cr-empty">No approved couriers for this sorting center yet. Approve one in Courier Registrations first.</td></tr>') : ''; $('vdPageInfo').textContent=rows.length?`Showing ${(page-1)*8+1}–${Math.min(page*8,rows.length)} of ${rows.length}`:'0 results';$('vdPageNo').textContent=page;$('vdPrev').disabled=page<=1;$('vdNext').disabled=page>=max;$('vdResultCount').textContent=rows.length+' records';}
function docs(r){const img=(k,label)=>{let url=r[k+'_url']||r[k]||r.documents?.[k]||'';const safe=typeof url==='string'&&(url.startsWith('/')&&!url.startsWith('//')||/^https:\/\//i.test(url));return `<div class="cr-photo">${safe?`<a href="${esc(url)}" target="_blank" rel="noopener"><img src="${esc(url)}" alt="${esc(label)}"></a>`:`<div class="empty">No ${esc(label)} uploaded</div>`}<strong>${esc(label)}</strong><small>${safe?'Click to view document':'No document URL available'}</small></div>`};return `<div class="cr-photos">${img('or_cr','OR / CR')}${img('drivers_license','Driver’s License')}</div>`;}
function courierDetail(r){const birth=val(r,'birthday','birth_date');const bd=new Date(birth);const age=isNaN(bd)?val(r,'age'):Math.max(0,new Date(Date.now()-bd.getTime()).getUTCFullYear()-1970);return `<div class="cr-profile"><span class="cr-avatar">${esc(initials(fullName(r)))}</span><div><strong>${esc(fullName(r))}</strong><small>Courier / Truck Driver · <span class="cr-badge approved">Approved</span></small></div></div>${section('Personal Information',`<div class="cr-grid">${field('Last Name',val(r,'last_name'))}${field('First Name',val(r,'first_name'))}${field('Middle Name',val(r,'middle_name'))}${field('Sex',val(r,'sex'))}${field('Birthday',birth)}${field('Age',age)}${field('Email Address',val(r,'email'))}${field('Contact Number',val(r,'phone','contact_no','contact_number'))}${field('Date Registered',date(r.created_at))}${field('Approved At',date(r.reviewed_at||r.approved_at))}</div>`)}${section('Address Information',`<div class="cr-grid">${field('Region',val(r,'region'))}${field('Province',val(r,'province'))}${field('Municipality / City',val(r,'city','municipality'))}${field('Barangay',val(r,'barangay'))}${field('Street',val(r,'street'))}${field('House Number',val(r,'house_no','house_number'))}${field('ZIP Code',val(r,'postal_code','zip_code'))}</div>`)}${section('Vehicle Information',`<div class="cr-grid">${field('Vehicle Type',val(r,'vehicle','vehicle_type'))}${field('Plate Number',val(r,'plate_number'))}</div>`)}${section('Uploaded Documents',docs(r))}<p class="vd-details-caption">Document previews appear only when the backend supplies accessible URLs. Passwords are not displayed.</p>`;}
function vehicleDetail(r){return `<div class="cr-profile"><span class="vd-vehicle-avatar">TRK</span><div><strong>${esc(val(r,'name','vehicle_name','model'))}</strong><small>Registered Vehicle · ${esc(val(r,'plate_number'))}</small></div></div>${section('Vehicle Information',`<div class="cr-grid">${field('Vehicle / Unit',val(r,'name','vehicle_name'))}${field('Vehicle Type',val(r,'type','vehicle_type'))}${field('Plate Number',val(r,'plate_number'))}${field('Manufacturer',val(r,'make','brand'))}${field('Model',val(r,'model'))}${field('Year',val(r,'year'))}${field('Color',val(r,'color'))}${field('Capacity',val(r,'capacity'))}${field('Availability',val(r,'availability','status'))}${field('Registered At',date(r.registration_date||r.created_at))}</div>`)}${section('Assignment Information',`<div class="cr-grid">${field('Assigned Driver',val(r,'driver_name','assigned_driver'))}${field('Sorting Center',val(r,'sorting_center_name','branch_name')==='—'?'Current Sorting Center':val(r,'sorting_center_name','branch_name'))}</div>`)}${section('Additional Notes',`<p class="cr-help">${esc(val(r,'notes','description'))}</p>`)}${section('Vehicle Documents',`<div class="cr-photos">${(()=>{let u=r.or_cr_url||r.or_cr||'';const safe=typeof u==='string'&&(u.startsWith('/')&&!u.startsWith('//')||/^https:\/\//i.test(u));return `<div class="cr-photo">${safe?`<a href="${esc(u)}" target="_blank" rel="noopener"><img src="${esc(u)}" alt="Vehicle OR / CR"></a>`:'<div class="empty">No OR / CR uploaded</div>'}<strong>OR / CR</strong></div>`})()}</div>`)}`;}
function showDetails(type,id){const r=available(type).find(x=>String(x.id)===String(id));if(!r)return;selected={type,id:String(id)};$('vdDetailTitle').textContent=type==='couriers'?'Courier Details':'Vehicle Details';$('vdDetailSubtitle').textContent=type==='couriers'?'Approved registration information and uploaded documents.':'Registered truck and assignment information.';$('vdDetailBody').innerHTML=type==='couriers'?courierDetail(r):vehicleDetail(r);setModal('vdDetailModal',true);}
$('vdVehicleRows').addEventListener('click',e=>{const row=e.target.closest('tr[data-key]');if(row)showDetails('vehicles',row.dataset.key)});$('vdCourierRows').addEventListener('click',e=>{const row=e.target.closest('tr[data-key]');if(row)showDetails('couriers',row.dataset.key)});
for(let id of ['vdVehicleRows','vdCourierRows']){$(id).addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){let tr=e.target.closest('tr[data-key]');if(tr){e.preventDefault();showDetails(id==='vdVehicleRows'?'vehicles':'couriers',tr.dataset.key)}}})}
const reasons={couriers:['Inactive or no longer affiliated with this Sorting Center','Duplicate approved courier record','Invalid or expired driver documents','Violation of operating requirements','Requested removal by courier','Other (please specify)'],vehicles:['Vehicle retired or permanently out of service','Vehicle transferred to another facility','Registration / OR-CR expired','Duplicate vehicle record','Vehicle no longer assigned to this Sorting Center','Other (please specify)']};
$('vdDelete').onclick=()=>{if(!selected)return;$('vdReasonOptions').innerHTML=reasons[selected.type].map(r=>`<label><input type="radio" name="vdReason" value="${esc(r)}"><span>${esc(r)}</span></label>`).join('');$('vdOtherReason').value='';$('vdReasonError').textContent='';setModal('vdDeleteModal',true)};
async function archiveSelected(){if(!selected)return;const reason=document.querySelector('input[name="vdReason"]:checked')?.value,notes=$('vdOtherReason').value.trim();if(!reason){$('vdReasonError').textContent='Please select a reason.';return}if(reason.startsWith('Other')&&!notes){$('vdReasonError').textContent='Please specify the reason.';return}try{const result=await api(`/api/v1/sorting_center/fleet/${selected.type}/${encodeURIComponent(selected.id)}/archive`,{method:'POST',body:JSON.stringify({reason:reason+(notes?' — '+notes:'')})});archive.push(result.data);closeAll();draw();flash('Record Archived',(selected.type==='vehicles'?'Vehicle':'Courier')+' moved to Trash. You can restore it anytime.');selected=null}catch(error){$('vdReasonError').textContent=error.message;flash('Archive Failed',error.message,true)}}
$('vdConfirmDelete').onclick=archiveSelected;
function drawArchive(){const q=$('vdArchiveSearch').value.toLowerCase().trim();const arr=archive.filter(a=>JSON.stringify(a).toLowerCase().includes(q));$('vdArchiveList').innerHTML=arr.map(a=>`<div class="vd-archive-row"><div><strong>${esc(a.type==='vehicles'?val(a.snapshot,'name','vehicle_name','plate_number'):fullName(a.snapshot))}</strong><small>${esc(a.type==='vehicles'?'Vehicle / Truck':'Approved Courier')} · Archived: ${esc(date(a.archived_at))}</small><small>Reason: ${esc(a.reason)}</small></div><button class="cr-btn approve sm" type="button" data-restore="${esc(a.key)}">Restore</button></div>`).join('')||'<div class="cr-empty" style="padding:40px">No archived items found.</div>'}
$('vdTrash').onclick=()=>{$('vdArchiveSearch').value='';drawArchive();setModal('vdArchiveModal',true)};
$('vdArchiveSearch').oninput=drawArchive;
$('vdArchiveList').onclick=async e=>{const button=e.target.closest('[data-restore]');if(!button)return;const a=archive.find(x=>x.key===button.dataset.restore);if(!a)return;try{await api(`/api/v1/sorting_center/fleet/${a.type}/${encodeURIComponent(a.id)}/restore`,{method:'POST',body:'{}'});archive=archive.filter(x=>x.key!==a.key);drawArchive();draw();flash('Record Restored','The item is available again in its original tab.')}catch(error){flash('Restore Failed',error.message,true)}};
$('vdReset').onclick=()=>{$('vdSearch').value='';page=1;draw()};$('vdSearch').oninput=()=>{page=1;draw()};$('vdPrev').onclick=()=>{page--;draw()};$('vdNext').onclick=()=>{page++;draw()};
document.querySelectorAll('.vd-tab').forEach(b=>b.addEventListener('click',()=>{activeTab=b.dataset.tab;page=1;document.querySelectorAll('.vd-tab').forEach(x=>{let on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-selected',String(on))});$('vdVehiclesPanel').hidden=activeTab!=='vehicles';$('vdCouriersPanel').hidden=activeTab!=='couriers';$('vdSearch').value='';draw()}));
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeAll);document.querySelectorAll('[data-close-reason]').forEach(b=>b.onclick=()=>setModal('vdDeleteModal',false));document.querySelectorAll('.cr-modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m){if(m.id==='vdDeleteModal')setModal('vdDeleteModal',false);else closeAll()}}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('vdDeleteModal').hidden)setModal('vdDeleteModal',false);else closeAll()}});$('vdFlashClose').onclick=()=>{$('vdFlash').hidden=true};
draw();
});
</script></body></html>
